const now = new Date();
const day = now.toLocaleDateString('es-MX', { weekday: 'long', timeZone: 'America/Mexico_City' });
const date = now.toLocaleDateString('es-MX', { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'America/Mexico_City' });

const themes = {
  'lunes': 'Disciplina y Hábitos',
  'martes': 'Entrenamiento y Técnica',
  'miércoles': 'Mentalidad Atlética',
  'jueves': 'Cuerpo y Estética',
  'viernes': 'Transformación Personal',
  'sábado': 'Proceso Real (sin filtros)',
  'domingo': 'Preparación y Estrategia'
};

const tema = themes[day.toLowerCase()] || 'Contenido General';

return { day, date, tema };

